// Single source of truth for the operator's remembered tool-permission
// decisions ("Allow always" / "Deny always"), persisted to localStorage so
// they survive a kato + browser restart.
//
// Why a shared store (not a per-hook useState): the permission PROMPT
// (App's useToolMemory) and the SETTINGS panel that lists + clears these
// decisions both read AND write the same set. If each kept its own
// in-memory copy, clearing one in settings would leave App's copy stale
// and it would keep auto-allowing what the operator just revoked — a real
// hole for a security control. One module-level map + pub/sub (same shape
// as toastStore / agentStatusStore) means every surface shares one value.

import { readStorageString, writeStorageItem } from '../utils/storage.js';
import { parseJsonOr } from '../utils/json.js';
import { createPubSub } from './pubsub.js';

export const TOOL_DECISIONS_STORAGE_KEY = 'kato.toolDecisions.v1';

// Exported (also re-exported by useToolMemory for back-compat) so the
// persistence layer can be unit-tested without React.
export function readPersisted() {
  const parsed = parseJsonOr(readStorageString(TOOL_DECISIONS_STORAGE_KEY, null), null);
  if (!parsed || typeof parsed !== 'object') { return {}; }
  return parsed;
}

export function writePersisted(decisions) {
  writeStorageItem(TOOL_DECISIONS_STORAGE_KEY, JSON.stringify(decisions), undefined);
}

let _decisions = readPersisted();
const _pubsub = createPubSub(() => _decisions);

function _commit(next) {
  _decisions = next;
  writePersisted(next);
  _pubsub.emit();
}

// Decisions are keyed by tool name, OR -- for command-keyed tools (Bash) --
// by `tool<NUL>command` so each exact command is its own remembered entry.
// NUL can't appear in a tool name or a shell command, so it splits the key
// unambiguously. Treat keys as OPAQUE: read them from entries() and pass
// them to setDecisionByKey()/forgetByKey(); use recall(tool, command) for
// lookups -- never rebuild a key by hand outside this module.
const CMD_SEP = '\u0000';

function _key(toolName, command) {
  const tool = String(toolName || '');
  const cmd = String(command || '').trim();
  return cmd ? `${tool}${CMD_SEP}${cmd}` : tool;
}

function _parseKey(key) {
  const sep = key.indexOf(CMD_SEP);
  if (sep === -1) { return { tool: key, command: '' }; }
  return { tool: key.slice(0, sep), command: key.slice(sep + 1) };
}

export const toolDecisionsStore = {
  subscribe: _pubsub.subscribe,

  get() { return _decisions; },

  // `command` (optional) scopes the lookup to an exact command for
  // command-keyed tools; omit it for tool-level decisions.
  recall(toolName, command = '') {
    if (!toolName) { return null; }
    return _decisions[_key(toolName, command)] || null;
  },

  // Stable list for the settings panel: one row per entry, with the parsed
  // tool + command. Sorted by tool, then command.
  entries() {
    return Object.keys(_decisions)
      .map((key) => ({ key, ..._parseKey(key), decision: _decisions[key] }))
      .sort((a, b) => a.tool.localeCompare(b.tool) || a.command.localeCompare(b.command));
  },

  // Set an explicit scope ('allow' | 'deny'). No-op + no emit when
  // unchanged, so a re-select of the current value can't loop.
  setDecision(toolName, decision, command = '') {
    if (!toolName) { return; }
    this.setDecisionByKey(_key(toolName, command), decision);
  },

  // Panel path: change scope of an existing entry by its stored key.
  setDecisionByKey(key, decision) {
    if (!key) { return; }
    const value = decision === 'deny' ? 'deny' : 'allow';
    if (_decisions[key] === value) { return; }
    _commit({ ..._decisions, [key]: value });
  },

  remember(toolName, allow, command = '') {
    this.setDecision(toolName, allow ? 'allow' : 'deny', command);
  },

  // forget(tool[, command]) drops one entry; forget() (no args) clears all.
  forget(toolName, command = '') {
    if (!toolName) {
      if (Object.keys(_decisions).length === 0) { return; }
      _commit({});
      return;
    }
    this.forgetByKey(_key(toolName, command));
  },

  // Panel path: drop an existing entry by its stored key.
  forgetByKey(key) {
    if (!key || !(key in _decisions)) { return; }
    const next = { ..._decisions };
    delete next[key];
    _commit(next);
  },

  // Cross-tab sync: another browser tab persisted a change; re-read the
  // canonical localStorage value and notify local subscribers.
  syncFromStorage() {
    _decisions = readPersisted();
    _pubsub.emit();
  },
};
